function deepClone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') return value;
  if (value instanceof Date) return new Date(value);
  if (value instanceof RegExp) return new RegExp(value.source, value.flags);
  if (seen.has(value)) return seen.get(value); // circular ref
  const copy = Array.isArray(value) ? [] : {};
  seen.set(value, copy);
  for (const key of Reflect.ownKeys(value)) {
    copy[key] = deepClone(value[key], seen);
  }
  return copy;
}

const a = { x: 1, n: { y: 2 } };
a.self = a; // circular
const b = deepClone(a);
b.n.y = 99;
console.log(a.n.y, b.n.y, b.self === b); // 2 99 true

function flatten(arr, depth = 1) {
  return depth > 0
    ? arr.reduce(
        (acc, cur) =>
          acc.concat(Array.isArray(cur) ? flatten(cur, depth - 1) : cur),
        []
      )
    : arr.slice();
}

console.log(flatten([1, [2, [3, [4]]]]));          // [1, 2, [3, [4]]]
console.log(flatten([1, [2, [3, [4]]]], Infinity)); // [1, 2, 3, 4]

Array.prototype.myMap = function (cb, thisArg) {
  const result = [];
  for (let i = 0; i < this.length; i++) {
    if (i in this) result[i] = cb.call(thisArg, this[i], i, this);
  }
  return result;
};

Array.prototype.myReduce = function (cb, initialValue) {
  let acc = initialValue;
  let start = 0;
  if (arguments.length < 2) {
    if (this.length === 0) throw new TypeError('Reduce of empty array with no initial value');
    acc = this[0];
    start = 1;
  }
  for (let i = start; i < this.length; i++) {
    acc = cb(acc, this[i], i, this);
  }
  return acc;
};

console.log([1, 2, 3].myMap((x) => x * 2));            // [2, 4, 6]
console.log([1, 2, 3, 4].myReduce((a, b) => a + b, 0)); // 10

